import React, { useEffect, useState } from 'react';
import { useTranslation } from '../hooks/useTranslation';

const SobreMim = () => {
  const { t } = useTranslation();
  const [displayPrefix, setDisplayPrefix] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [isTypingComplete, setIsTypingComplete] = useState(false);
  const [startTyping, setStartTyping] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setStartTyping(true);
    }, 600);

    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!startTyping) return;

    const prefix = t('hero_prefix');
    const name = t('hero_name');
    let index = 0;
    let timeoutId;

    const typeNextChar = () => {
      if (index < prefix.length + name.length + 1) {
        if (index < prefix.length) {
          setDisplayPrefix(prefix.substring(0, index + 1));
        } else if (index === prefix.length) {
          setDisplayPrefix(prefix);
        } else {
          const nameIndex = index - prefix.length - 1;
          setDisplayName(name.substring(0, nameIndex + 1));
        }
        index++;
        const delay = index === prefix.length ? 300 : 80;
        timeoutId = setTimeout(typeNextChar, delay);
      } else {
        setIsTypingComplete(true);
      }
    };

    typeNextChar();

    return () => clearTimeout(timeoutId);
  }, [t, startTyping]);

  return (
    <section id="hero" className="hero">
      <div className="hero-background-image"></div>
      <div className="hero-overlay"></div>

      <div className="hero-content-left" data-aos="fade-up">
        <div className="hero-top" data-aos="fade-up" data-aos-delay="100">
          <div className="hero-greeting">{t('hero_title')}</div>
        </div>

        <div className="hero-info" data-aos="fade-up" data-aos-delay="200">
          <div className="hero-name-wrapper">
            <span className="hero-prefix">
              {displayPrefix}
              {displayPrefix === t('hero_prefix') && !isTypingComplete && startTyping && (
                <span className="hero-cursor"></span>
              )}
            </span>
            <h1 className="hero-name">
              {displayName}
              {!isTypingComplete && startTyping ? (
                <span className="hero-cursor"></span>
              ) : null}
            </h1>
          </div>
          <p className="hero-role">{t('hero_role')}</p>
<div className="hero-tags" data-aos="fade-up" data-aos-delay="300">
  <span data-translate="hero_tag_frontend">{t('hero_tag_frontend')}</span>
  <span data-translate="hero_tag_backend">{t('hero_tag_backend')}</span>
  <span data-translate="hero_tag_agile">{t('hero_tag_agile')}</span>
  <span data-translate="hero_tag_uiux">{t('hero_tag_uiux')}</span>
</div>
        </div>

        <div className="hero-social" data-aos="fade-up" data-aos-delay="400">
          <a href="https://github.com/MatheusAbib" target="_blank" rel="noopener noreferrer">
            <i className="bi bi-github"></i>
          </a>
          <a href="https://www.linkedin.com/in/matheusabib/" target="_blank" rel="noopener noreferrer">
            <i className="bi bi-linkedin"></i>
          </a>
          <a href="https://wa.me/11975072008" target="_blank" rel="noopener noreferrer">
            <i className="bi bi-whatsapp"></i>
          </a>
        </div>
      </div>
    </section>
  );
};

export default SobreMim;
